// further languages (EFIGS, LATAM, CJK) live in ./i18n/<lang>.ts; a missing key falls back to English
const DICTS: Record<Lang, Partial<Record<Key, Entry>>> = { en, de, fr, it, es, "es-419": es419, "pt-BR": ptBR, ja, ko, "zh-Hans": zhHans, "zh-Hant": zhHant };
export const LANGS: [Lang, string][] = [["en", "English"], ["de", "Deutsch"], ["fr", "Français"], ["it", "Italiano"], ["es", "Español (España)"],
  ["es-419", "Español (Latinoamérica)"], ["pt-BR", "Português (Brasil)"], ["ja", "日本語"], ["ko", "한국어"], ["zh-Hans", "简体中文"], ["zh-Hant", "繁體中文"]];
/** first start: the system language when Fumika has it (es-MX -> es-419, zh-TW -> zh-Hant, pt-PT -> pt-BR) */
function systemLang(): Lang {
  const l = (navigator.language || "en").toLowerCase();
  if (l.startsWith("zh")) return /tw|hk|mo|hant/.test(l) ? "zh-Hant" : "zh-Hans";
  if (l.startsWith("es")) return l === "es" || l.startsWith("es-es") ? "es" : "es-419";
  if (l.startsWith("pt")) return "pt-BR";
  const two = l.slice(0, 2) as Lang;
  return Object.prototype.hasOwnProperty.call(DICTS, two) ? two : "en";
}
const PREFS = "fumika-prefs";

function stored(): { lang?: Lang; theme?: Theme; palette?: Palette; expert?: boolean } {
  let p: { lang?: Lang; theme?: Theme; palette?: Palette; expert?: boolean } = {};
  try { p = JSON.parse(localStorage.getItem(PREFS) || "{}") ?? {}; } catch { /* defaults */ }
  // ?lang=de&theme=dark&palette=terra: preview captures of the browser demo
  const q = new URLSearchParams(location.search);
  return { lang: (q.get("lang") as Lang) ?? p.lang, theme: (q.get("theme") as Theme) ?? p.theme,
    palette: (q.get("palette") as Palette) ?? p.palette, expert: q.has("expert") || !!p.expert };
}

export const prefs = $state({ lang: (stored().lang && Object.prototype.hasOwnProperty.call(DICTS, stored().lang!) ? stored().lang! : systemLang()) as Lang, theme: (stored().theme ?? "system") as Theme,
  palette: (stored().palette === "terra" ? "terra" : "fumika") as Palette,
  /** expert mode: sampler / steps / cfg / strengths per project, trainer details (default off = the tested settings) */
  expert: !!stored().expert });

/** apply language, theme and colour scheme to the document and remember them */
export function applyPrefs() {
  const root = document.documentElement;
  root.lang = prefs.lang;
  if (prefs.theme === "system") delete root.dataset.theme; else root.dataset.theme = prefs.theme;
  if (prefs.palette === "fumika") delete root.dataset.palette; else root.dataset.palette = prefs.palette;
  try { localStorage.setItem(PREFS, JSON.stringify(prefs)); } catch { /* private window: defaults next time */ }
  // the tray menu is native: send it the labels of the new language
  if ("__TAURI_INTERNALS__" in window) invoke("tray_labels", { show: t("tray.show"), quit: t("tray.quit") }).catch(() => {});
}

/** translate; {name} placeholders, [one, other] entries pick by vars.n */
export function t(key: Key, vars: Record<string, string | number> = {}): string {
  const e = DICTS[prefs.lang][key] ?? en[key];
  const s = Array.isArray(e) ? (vars.n === 1 ? e[0] : e[1]) : e;
  return s.replace(/\{(\w+)\}/g, (_, k) => (k in vars ? String(vars[k]) : `{${k}}`));
}

/** numbers in the UI language (decimal comma in German, French, ...) */
export const num = (x: number, digits = 1) =>
  x.toLocaleString(prefs.lang, { minimumFractionDigits: digits, maximumFractionDigits: digits });

/** job labels are stored language-neutral ("Page 4"); older ones are German ("Seite 4") */
export function jobLabel(label: string): string {
  if (label === "Cover") return t("cover.title");
  const m = label.match(/^(?:Page|Seite) (\d+)$/);
  if (m) return t("page.n", { n: m[1] });
  const tr = label.match(/^train-(check|start|epochs) (.+)$/);   // trainer jobs, e.g. "train-check fumika"
  const keys = { check: "job.trainCheck", start: "job.trainStart", epochs: "job.trainEpochs" } as const;
  if (tr) return t(keys[tr[1] as keyof typeof keys], { name: tr[2] });
  const im = label.match(/^image-(t2i|i2i|inpaint|upscale)$/);   // Image Studio jobs
  if (im) return t(`img.m.${im[1]}` as Key);
  const fr = label.match(/^freeze (.+)$/);   // freeze the look of a scene
  if (fr) return t("job.freeze", { name: fr[1] });
  const a = label.match(/^asset-(\w+) (.+)$/);   // Asset Studio jobs, e.g. "asset-expressions Fumika"
  return a ? t("job.asset", { type: t(`as.t.${a[1]}` as Key), name: a[2] }) : label;
}
